def btn(label,href,outline=False):
    ext=' target="_blank" rel="noopener noreferrer"' if href.startswith('https://www.') else ''
    return f'<a class="button{" outline" if outline else ""}" href="{href}"{ext}>{escape(label)}<span class="arrow" aria-hidden="true">↗</span></a>'
def languages(key,case=False):
    if case: urls=['../../projects/utopia.html','../../pt/projects/utopia.html'] if key=='pt' else ['utopia.html','../pt/projects/utopia.html']
    else: urls=['../index.html','index.html'] if key=='pt' else ['index.html','pt/index.html']
    return '<nav class="languages" aria-label="Language / Idioma">'+''.join(f'<a href="{url}" lang="{code}" hreflang="{code}"'+(' aria-current="page"' if key==code else '')+f'>{code.upper()}</a>'+('<span aria-hidden="true">/</span>' if code=='en' else '') for code,url in zip(['en','pt'],urls))+'</nav>'
def sheet(d,full=False,demo=False):
    attrs=''.join(f'<label class="attribute"><span class="mono">{a}</span><input type="number" min="0" max="99" value="2" aria-label="{a}"></label>' if demo else f'<div class="attribute"><span class="mono">{a}</span><strong>02</strong></div>' for a in d['attrs'])
    bars=''.join(f'<div class="resource"><div class="resource-title mono"><span>{l}</span><span><output>{v} / {m}</output></span></div>'+ (f'<input data-resource type="range" min="0" max="{m}" value="{v}" aria-label="{l}">' if demo else '<div class="meter"><span></span></div>')+'</div>' for l,v,m in zip(d['resources'],[18,12,8],[24,16,12]))
    blocks=''.join('<div class="sheet-block"><span class="mono">'+d[k]+'</span><ul>'+''.join('<li>'+escape(v)+'</li>' for v in d[l])+'</ul></div>' for k,l in [('skills','skillList'),('equipment','equipmentList')])
    identity=f'<label><span class="mono">{d["char"]}</span><input class="demo-name" aria-label="{d["name"]}" value="{d["identity"]}" maxlength="60"></label>' if demo else f'<div class="sheet-identity"><span class="mono">{d["char"]}</span><h3>{d["identity"]}</h3></div>'
    if demo:
        tabs='<div class="sheet-tabs" role="tablist" aria-label="UTOPIA">'+''.join(f'<button type="button" role="tab" id="tab-{i}" aria-controls="panel-{i}" aria-selected="{str(i==0).lower()}" tabindex="{0 if i==0 else -1}">{t}</button>' for i,t in enumerate(d['tabs']))+'</div>'
        contents=f'<div class="sheet-grid" id="panel-0" role="tabpanel" aria-labelledby="tab-0">{blocks}</div>'
        contents+='<div class="sheet-grid" id="panel-1" role="tabpanel" aria-labelledby="tab-1" hidden><div class="sheet-block"><span class="mono">'+d['equipment']+'</span>'+''.join(f'<input aria-label="{x}" value="{x}" maxlength="80">' for x in d['equipmentList'])+'</div></div>'
        contents+='<div class="sheet-grid" id="panel-2" role="tabpanel" aria-labelledby="tab-2" hidden><div class="sheet-block"><span class="mono">'+d['implantLabel']+'</span>'+''.join(f'<input aria-label="{x}" value="{x}" maxlength="80">' for x in d['implants'])+'</div><p class="mono">'+d['implantNote']+'</p></div>'
        contents+=f'<div class="demo-controls"><label class="mono">{d["die"]} <select data-die>'+''.join(f'<option value="{n}"'+(' selected' if n==20 else '')+f'>d{n}</option>' for n in [4,6,8,10,12,20])+f'</select></label><button type="button" data-roll>{d["roll"]}</button><output class="dice-result" data-result aria-live="polite">{d["ready"]}</output></div><p class="demo-notice">{d["demoNotice"]}</p>'
    else:
        tabs='<div class="sheet-tabs">'+''.join(f'<span>{t}</span>' for t in d['tabs'])+'</div>'
        contents=f'<div class="sheet-grid">{blocks}</div>' if full else ''
    return f'<div class="sheet{" sheet-full" if full else ""}"><div class="sheet-top"><span class="sheet-logo">UTOPIA</span><span class="mono">{d["hub"]}</span></div>{identity}<div class="attributes">{attrs}</div>{bars}{tabs}{contents}<p class="mono sheet-note">{d["excerpt"]}</p></div>'
def head(d,key,prefix='',case=False):
    route=('pt/' if key=='pt' else '')+('projects/utopia.html' if case else 'index.html')
    title=('UTOPIA — '+d['title']) if case else d['title']
    home=BASE+('pt/' if key=='pt' else '')
    alt=BASE+('projects/utopia.html' if case else '')
    altpt=BASE+'pt/'+('projects/utopia.html' if case else '')
    schema={'@context':'https://schema.org','@type':'Person','name':'Harley Aguilar','alternateName':'Hude','url':home,'sameAs':['https://www.youtube.com/@Hudezin',IG,'https://www.tiktok.com/@hudeplay']}
    return f'''<!doctype html><html lang="{d['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#111310"><title>{escape(title)}</title><meta name="description" content="{escape(d['description'])}"><link rel="canonical" href="{BASE+route}"><link rel="alternate" hreflang="en" href="{alt}"><link rel="alternate" hreflang="pt-BR" href="{altpt}"><link rel="alternate" hreflang="x-default" href="{alt}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(d['description'])}"><meta property="og:url" content="{BASE+route}"><link rel="icon" type="image/svg+xml" href="{prefix}assets/favicon.svg"><link rel="stylesheet" href="{prefix}assets/style.css"><script src="{prefix}assets/app.js" defer></script><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><a class="skip" href="#main">{d['skip']}</a>'''
def footer(d,home='index.html'):
    return f'<footer class="footer wrap"><a class="wordmark" href="{home}">HUDE<sup>®</sup></a><p class="mono">{d["footer"]}</p><p class="mono">© 2026 · {d["country"]}</p></footer></body></html>'
def contact(d,case=False):
    return '<section class="contact" id="contact"><div class="wrap"><p class="eyebrow">'+d['next']+'</p><h2>'+d['caseContact' if case else 'contactTitle']+'</h2><p>'+d['caseContactText' if case else 'contactText']+'</p>'+btn(d['caseContactButton' if case else 'message'],IG,True)+'</div></section>'
def home(key):
    d=D[key];pre='../' if key=='pt' else ''
    nav=''.join(f'<a href="#{section}">{label}</a>' for section,label in zip(['work','services','process'],d['nav']))
    features=''.join(f'<li>{i:02d}&nbsp;&nbsp; {escape(t)}</li>' for i,t in enumerate(d['features'],1))
    cards=''.join(f'<article class="service-card"><span class="eyebrow">{i:02d}</span><h3>{title}</h3><p>{desc}</p><p class="mono card-tag">{escape(tag)}</p></article>' for i,(title,desc,tag) in enumerate(d['services'],1))
    steps=''.join(f'<article class="step"><span class="eyebrow">{i:02d}</span><h3>{title}</h3><p>{desc}</p></article>' for i,(title,desc) in enumerate(d['steps'],1))
    socials=''.join(f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} <span aria-hidden="true">↗</span></a>' for label,url in [('YouTube','https://www.youtube.com/@Hudezin'),('Instagram',IG),('TikTok','https://www.tiktok.com/@hudeplay')])
    return head(d,key,pre)+f'''<header class="site-header"><div class="nav wrap"><a class="wordmark" href="index.html" aria-label="Hude — Home">HUDE<sup>®</sup></a><nav class="nav-links" id="nav-links" aria-label="{'Navegação principal' if key=='pt' else 'Main navigation'}">{nav}</nav>{languages(key)}{btn(d['talk'],IG,True)}<button class="menu-toggle" type="button" aria-label="{d['menu']}" aria-controls="nav-links" aria-expanded="false"><span aria-hidden="true">☰</span></button></div></header><main id="main"><section class="hero wrap"><div class="hero-copy"><p class="eyebrow">{d['eyebrow']}</p><h1>'''+''.join(f'<span'+(' class="accent"' if i==1 else '')+f'>{t}</span>' for i,t in enumerate(d['hero']))+f'''</h1><p class="intro">{d['intro']}</p>{btn(d['explore'],'#work')}<p class="mono muted byline">HUDE / HARLEY AGUILAR · {d['country']}</p></div><figure class="hero-visual">{sheet(d)}<figcaption class="mono">{d['sheetLabel']}</figcaption></figure></section><div class="specialties mono">'''+''.join(f'<span>{t}</span>' for t in d['specialties'])+f'''</div><section class="section work" id="work"><div class="wrap"><div class="section-heading"><p class="eyebrow">{d['selected']}</p><h2>{d['worktitle']}</h2></div><article class="project-grid"><div class="preview-frame">{sheet(d,True)}</div><div class="project-summary"><p class="eyebrow">{d['caseLabel']}</p><h3>UTOPIA</h3><p class="subtitle">{d['subtitle']}</p><p class="description">{d['projectdesc']}</p><ul class="feature-list mono">{features}</ul>{btn(d['inside'],'projects/utopia.html')}<p class="mono note">{d['local']}</p></div></article></div></section><section class="section wrap" id="services"><div class="section-heading"><p class="eyebrow">{d['servicesLabel']}</p><h2>{d['servicesTitle']}</h2></div><div class="cards">{cards}</div></section><section class="section process wrap" id="process"><div class="section-heading"><p class="eyebrow">{d['processLabel']}</p><h2>{d['processTitle']}</h2></div><div class="steps">{steps}</div></section><section class="about"><div class="about-grid wrap"><div><p class="eyebrow">{d['creator']}</p><h2>{d['aboutTitle']}</h2></div><div class="about-copy"><p>{d['bio']}</p><nav class="socials" aria-label="Social">{socials}</nav></div></div></section>{contact(d)}</main>'''+footer(d)
def case(key):
    d=D[key];pre='../../' if key=='pt' else '../'
    decisions=''.join(f'<article class="step"><h3>{title}</h3><p>{text}</p></article>' for title,text in d['decisions'])
    return head(d,key,pre,True)+f'''<header class="site-header"><div class="case-nav wrap"><a class="back" href="../index.html#work">← {d['back']}</a><a class="mono muted" href="../index.html">HUDE® / UTOPIA</a>{languages(key,True)}</div></header><main id="main"><section class="case-intro wrap"><p class="eyebrow">{d['caseEyebrow']}</p><h1>UTOPIA</h1><h2>{d['caseTitle']}</h2><p>{d['caseIntro']}</p></section><section class="case-visual"><div class="wrap demo" data-demo>{sheet(d,True,True)}<p class="demo-help">{d['demoHelp']}</p></div></section><section class="case-detail wrap"><div class="steps">{decisions}</div></section><section class="scope"><div class="wrap"><p class="eyebrow">{d['scopeLabel']}</p><h2>{d['scopeTitle']}</h2><p>{d['scope']}</p></div></section>{contact(d,True)}</main>'''+footer(d,'../index.html')
for key in D:
    folder=ROOT/('pt' if key=='pt' else '')
    (folder/'projects').mkdir(parents=True,exist_ok=True)
    (folder/'index.html').write_text(home(key),encoding='utf-8')
    (folder/'projects/utopia.html').write_text(case(key),encoding='utf-8')
(ROOT/'404.html').write_text(head(D['en'],'en','/Huderpg/')+'<main id="main" class="not-found wrap"><p class="eyebrow">404 / LOST IN THE MULTIVERSE</p><h1>Page not found.</h1><p class="muted">This page may have moved. Your next adventure starts on the portfolio.</p>'+btn('Back to the portfolio','/Huderpg/')+'</main>'+footer(D['en'],'/Huderpg/'),encoding='utf-8')
urls=['','pt/','projects/utopia.html','pt/projects/utopia.html']
(ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+BASE+p+'</loc></url>' for p in urls)+'</urlset>',encoding='utf-8')
(ROOT/'robots.txt').write_text('User-agent: *\nAllow: /Huderpg/\nSitemap: '+BASE+'sitemap.xml\n',encoding='utf-8')
print('Generated English and Portuguese home and case pages, 404, sitemap and robots.txt.')
